-- Growth1000 foundation. All exposed tables use RLS; authorization never trusts user_metadata.
create extension if not exists pgcrypto;
create type public.app_role as enum ('admin','staff','client');
create type public.record_status as enum ('active','inactive','archived');

create table public.organizations (id uuid primary key default gen_random_uuid(), name text not null, slug text not null unique, status public.record_status not null default 'active', is_demo boolean not null default false, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, full_name text not null, avatar_url text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.organization_members (organization_id uuid not null references public.organizations(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.app_role not null, status public.record_status not null default 'active', primary key (organization_id,user_id));
create table public.clients (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), name text not null, slug text not null, industry text, city text, country text not null default 'UAE', lifecycle_status text not null default 'onboarding', health_status text not null default 'healthy', is_demo boolean not null default false, deleted_at timestamptz, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(organization_id,slug));
create index clients_org_idx on public.clients(organization_id) where deleted_at is null;
create table public.client_members (client_id uuid not null references public.clients(id) on delete cascade, user_id uuid not null references public.profiles(id) on delete cascade, role public.app_role not null default 'client', primary key(client_id,user_id));
create table public.client_service_scopes (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, service_key text not null check(service_key in ('seo','social_media','blogs','website_maintenance','website_chatbot','whatsapp_ai','analytics_reporting')), label text not null, enabled boolean not null default true, monthly_quantity integer check(monthly_quantity is null or monthly_quantity > 0), notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique(client_id,service_key));
create index client_service_scopes_client_idx on public.client_service_scopes(client_id) where enabled;
create table public.business_profiles (client_id uuid primary key references public.clients(id) on delete cascade, description text, target_customers text, value_proposition text, tone_of_voice text, business_hours text, phone text, whatsapp text, email text, website text, offers text, competitors text, important_claims text, prohibited_claims text, updated_at timestamptz not null default now());
create table public.business_services (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, name text not null, description text, status public.record_status not null default 'active');
create table public.business_locations (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, name text not null, status public.record_status not null default 'active');
create table public.business_faqs (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, question text not null, answer text not null, verified boolean not null default false);
create table public.client_access (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, access_type text not null, platform text, status text not null default 'not_connected', account_reference text, credential_reference text, notes text, verified_at timestamptz, verified_by uuid references public.profiles(id), unique(client_id,access_type));
create table public.client_integrations (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, provider text not null, status text not null default 'not_connected', is_demo boolean not null default false, external_reference text, last_synced_at timestamptz, unique(client_id,provider));
create table public.assets (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, filename text not null, mime_type text, category text not null, storage_path text not null, source text not null default 'uploaded', created_by uuid references public.profiles(id), created_at timestamptz not null default now(), deleted_at timestamptz);
create index assets_client_idx on public.assets(client_id,category) where deleted_at is null;
create table public.tasks (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, title text not null, description text, category text not null, assigned_user_id uuid references public.profiles(id), assigned_role public.app_role, due_at timestamptz, priority text not null default 'medium', status text not null default 'not_started', source text not null default 'manual', related_type text, related_id uuid, deliverable_month date, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index tasks_client_status_idx on public.tasks(client_id,status);
create table public.task_comments (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, author_id uuid not null references public.profiles(id), body text not null, is_internal boolean not null default true, created_at timestamptz not null default now());
create table public.task_activity (id uuid primary key default gen_random_uuid(), task_id uuid not null references public.tasks(id) on delete cascade, actor_id uuid references public.profiles(id), action text not null, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.content_items (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, content_kind text not null, month date, platform text, topic text, concept text, caption text, hashtags text, creative_brief text, target_keyword text, body text, seo_metadata jsonb, recommended_publish_at timestamptz, internal_notes text, status text not null default 'idea', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index content_client_month_idx on public.content_items(client_id,month,status);
create table public.content_assets (content_item_id uuid not null references public.content_items(id) on delete cascade, asset_id uuid not null references public.assets(id) on delete cascade, prompt text, model text, version integer not null default 1, generation_status text, primary key(content_item_id,asset_id));
create table public.content_approvals (id uuid primary key default gen_random_uuid(), content_item_id uuid not null references public.content_items(id) on delete cascade, reviewer_id uuid not null references public.profiles(id), decision text not null, note text, created_at timestamptz not null default now());
create table public.seo_keywords (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, keyword text not null, intent text, target_url text, current_position integer, previous_position integer, priority text, status text, notes text);
create table public.seo_pages (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, url text not null, title text, target_keyword text, status text);
create table public.seo_tasks (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, task_id uuid references public.tasks(id), opportunity text, status text);
create table public.reports (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, month date not null, summary text, work_completed jsonb not null default '{}', analytics_summary jsonb, next_month_focus text, status text not null default 'draft', asset_id uuid references public.assets(id), unique(client_id,month));
create table public.client_requests (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, requester_id uuid not null references public.profiles(id), request_type text not null, title text not null, description text, status text not null default 'received', created_at timestamptz not null default now());
create table public.automation_jobs (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), workflow_key text not null, name text not null, status text not null default 'active', configuration jsonb not null default '{}', unique(organization_id,workflow_key));
create table public.automation_runs (id uuid primary key default gen_random_uuid(), job_id uuid not null references public.automation_jobs(id), client_id uuid references public.clients(id), started_at timestamptz not null default now(), finished_at timestamptz, status text not null default 'running', input_reference jsonb, output_reference jsonb, cost numeric(12,6));
create table public.automation_errors (id uuid primary key default gen_random_uuid(), run_id uuid not null references public.automation_runs(id) on delete cascade, error_code text, message text not null, details jsonb, created_at timestamptz not null default now());
create table public.notifications (id uuid primary key default gen_random_uuid(), user_id uuid not null references public.profiles(id) on delete cascade, title text not null, body text, read_at timestamptz, created_at timestamptz not null default now());
create table public.audit_logs (id uuid primary key default gen_random_uuid(), organization_id uuid not null references public.organizations(id), client_id uuid references public.clients(id), actor_id uuid references public.profiles(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create table public.analytics_daily (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, day date not null, metrics jsonb not null, is_demo boolean not null default false, unique(client_id,day));
create table public.search_console_daily (id uuid primary key default gen_random_uuid(), client_id uuid not null references public.clients(id) on delete cascade, day date not null, query text not null default '', page text not null default '', metrics jsonb not null, is_demo boolean not null default false, unique(client_id,day,query,page));

create schema if not exists private;
create function private.is_org_admin(org_id uuid) returns boolean language sql stable security invoker set search_path='' as $$ select exists(select 1 from public.organization_members m where m.organization_id=org_id and m.user_id=(select auth.uid()) and m.role='admin' and m.status='active') $$;
create function private.can_access_client(target_client uuid) returns boolean language sql stable security invoker set search_path='' as $$ select exists(select 1 from public.clients c where c.id=target_client and (private.is_org_admin(c.organization_id) or exists(select 1 from public.organization_members m where m.organization_id=c.organization_id and m.user_id=(select auth.uid()) and m.role='staff' and m.status='active') or exists(select 1 from public.client_members cm where cm.client_id=c.id and cm.user_id=(select auth.uid())))) $$;
revoke all on all functions in schema private from public, anon, authenticated;
grant usage on schema private to authenticated;
grant execute on function private.is_org_admin(uuid), private.can_access_client(uuid) to authenticated;

do $$ declare t text; begin foreach t in array array['organizations','profiles','organization_members','clients','client_members','client_service_scopes','business_profiles','business_services','business_locations','business_faqs','client_access','client_integrations','assets','tasks','task_comments','task_activity','content_items','content_assets','content_approvals','seo_keywords','seo_pages','seo_tasks','reports','client_requests','automation_jobs','automation_runs','automation_errors','notifications','audit_logs','analytics_daily','search_console_daily'] loop execute format('alter table public.%I enable row level security',t); end loop; end $$;
create policy "members read own organization" on public.organizations for select to authenticated using (exists(select 1 from public.organization_members m where m.organization_id=id and m.user_id=(select auth.uid())));
create policy "users read own profile" on public.profiles for select to authenticated using (id=(select auth.uid()));
create policy "members read organization membership" on public.organization_members for select to authenticated using (user_id=(select auth.uid()) or private.is_org_admin(organization_id));
create policy "authorized users read clients" on public.clients for select to authenticated using (private.can_access_client(id));
create policy "admins manage clients" on public.clients for all to authenticated using (private.is_org_admin(organization_id)) with check (private.is_org_admin(organization_id));
do $$ declare t text; begin foreach t in array array['business_profiles','business_services','business_locations','business_faqs','client_access','client_integrations','assets','tasks','content_items','seo_keywords','seo_pages','seo_tasks','reports','client_requests','analytics_daily','search_console_daily'] loop execute format('create policy "authorized client rows" on public.%I for select to authenticated using (private.can_access_client(client_id))',t); end loop; end $$;
create policy "client creates own requests" on public.client_requests for insert to authenticated with check (private.can_access_client(client_id) and requester_id=(select auth.uid()));
create policy "users read own notifications" on public.notifications for select to authenticated using (user_id=(select auth.uid()));
grant select,insert,update,delete on all tables in schema public to authenticated;
